    #Node Switch
    def switch( self, switch: Boolean = None, true: Vector = None):
        """Node Switch.
        
        Jump: True
        
        **Fixed inputs**
        - Node parameter 'input_type' = 'VECTOR'
        
        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        true : Vector, optional
            Socket 'True' (default: None)
        

        Returns
        -------
        Self
            The updated receiver, or its owning geometry for a domain.
            Updates self from the default output socket.
        """
        node = Node(
            'Switch',
            named_sockets={'ID_Switch': switch, 'ID_False': self, 'ID_True': true},
            input_type='VECTOR')
        
        self._jump(node._out)
        return self.self_return

    #Node Vector Math
    def vector_math(
        self,
        vector: Vector = None,
        addend: Vector = None,
        ior: Float = None,
        *,
        multiplier: Vector = None,
        incident: Vector = None,
        exponent: Vector = None,
        max: Vector = None,
        increment: Vector = None,
        reference: Vector = None,
        min: Vector = None,
        scale: Float = None,
        operation: T_OPERATION_4 = 'ADD'):
        """Node Vector Math.
        
        Jump: False
        
        Parameters
        ----------
        operation : {'ADD', 'SUBTRACT', 'MULTIPLY', 'DIVIDE', 'MULTIPLY_ADD', 'CROSS_PRODUCT', 'PROJECT', 'REFLECT', 'REFRACT', 'FACEFORWARD', 'DOT_PRODUCT', 'DISTANCE', 'LENGTH', 'SCALE', 'NORMALIZE', 'ABSOLUTE', 'POWER', 'SIGN', 'MINIMUM', 'MAXIMUM', 'ROUND', 'FLOOR', 'CEIL', 'FRACTION', 'MODULO', 'WRAP', 'SNAP', 'SINE', 'COSINE', 'TANGENT'}, optional
            Node parameter 'operation' (default: 'ADD')
        vector : Vector, optional
            Alias of socket identifier: 'Vector_001' (default: None)
        multiplier : Vector, optional
            Alias of socket identifier: 'Vector_001' (default: None)
        incident : Vector, optional
            Alias of socket identifier: 'Vector_001' (default: None)
        exponent : Vector, optional
            Alias of socket identifier: 'Vector_001' (default: None)
        max : Vector, optional
            Alias of socket identifier: 'Vector_001' (default: None)
        increment : Vector, optional
            Alias of socket identifier: 'Vector_001' (default: None)
        addend : Vector, optional
            Alias of socket identifier: 'Vector_002' (default: None)
        reference : Vector, optional
            Alias of socket identifier: 'Vector_002' (default: None)
        min : Vector, optional
            Alias of socket identifier: 'Vector_002' (default: None)
        ior : Float, optional
            Alias of socket identifier: 'Scale' (default: None)
        scale : Float, optional
            Alias of socket identifier: 'Scale' (default: None)
        

        Returns
        -------
        Socket
            Default output socket.
        """
        node = Node(
            'Vector Math',
            named_sockets={'ID_Vector': self, 'ID_Vector_001': next((v for v in (vector, multiplier, incident, exponent, max, increment) if v is not None), None), 'ID_Vector_002': next((v for v in (addend, reference, min) if v is not None), None), 'ID_Scale': next((v for v in (ior, scale) if v is not None), None)},
            operation=operation)
        
        return node._out

